import math

def clamp_unit(x: float) -> float | None:
    if math.isnan(x):
        return None
    if x < 0:
        return None
    if x > 100:
        return None
    if 1 <= x <= 10:
        normalized = x / 10.0
    elif 10 < x <= 100:
        normalized = x / 100.0
    else:  # 0 <= x < 1
        normalized = x
    if normalized > 1 or normalized <= 0:
        return None
    return normalized

